using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 static readonly string[] FamilyTitles={"A SUMMER AT WILLOW HOUSE","THE LAST REPAIR","RATION BOOK / FINAL ENTRIES"};
 static readonly string[] FamilyNotes={"A sun-faded photograph: two parents, a child with a missing front tooth, and an infant held against a shoulder. Behind them, the garden is full of flowers. Someone wrote on the frame: 'First summer in our forever home.'","The kitchen note is pinned beneath a shopping list. 'Windows are done. I fixed the swing again. We can keep things normal upstairs for a little longer. If the road gets worse, we go below. The garage stores are locked away; the spare keys are on the safe-room table. Please don't let anyone forget them.'","The first pages list four names and neat portions. Later, the portions are halved, then halved again.\n\n'The shelving came down outside the door. I can hear it scrape, but it won't move. We left almost everything in the garage. The keys are here with us.'\n\n'They still ask whether we can go upstairs tomorrow. I keep saying soon.'\n\nSeveral pages are missing. The last entry is barely legible.\n\n'I tried to keep the room tidy. I don't know why that mattered. Please remember us in the garden.'\n\nThe rest of the book is blank."};
 bool FamilyWalkable(double x,double z)=>x> -5.7&&x<5.7&&z> -21.7&&z<3.7&&(z>= -8||game.World.Changes.FamilyDoorOpened);
 string FamilyOperation(){if(InFamilyRoom){if(Distance(player.Position,new(0,0,3))<2)return "exit";if(game.World.Changes.FamilyShelfDamage<54&&Distance(player.Position,new(0,0,-6.5f))<2.7)return "shelf";if(!game.World.Changes.FamilyDoorOpened&&Distance(player.Position,new(0,0,-8))<2.8)return "door";if(game.World.Changes.FamilyDoorOpened&&Distance(player.Position,new(2.2f,0,-12))<2.3)return game.World.Changes.FamilyKeys?"journal":"keys";return "";}if(dungeon!=null||Math.Abs(player.Position.Y-familyFloor)>1.5||!GodotObject.IsInstanceValid(familyHome)||!familyHome.IsInsideTree())return "";if(Distance(player.Position,FamilyPoint(10,0,4))<3&&!game.World.Changes.FamilyGarageOpen)return "garage";if(Distance(player.Position,FamilyPoint(10,0,0))<2.5&&game.World.Changes.FamilyGarageOpen)return "cache";if(Distance(player.Position,FamilyPoint(-3,0,-3))<2.3)return "basement";if(Distance(player.Position,FamilyPoint(-4,0,-5.4f))<2.5)return "photo";if(Distance(player.Position,FamilyPoint(2.6f,0,-2.8f))<2)return "letter";return "";}
 string FamilyPrompt()=>FamilyOperation() switch{"exit"=>"F / RETURN UPSTAIRS","shelf"=>"FALLEN SHELF / T EQUIP AXE / AIM AND SWING","door"=>"F / OPEN SAFE-ROOM DOOR","keys"=>"F / TAKE GARAGE KEYS","journal"=>"F / READ RATION BOOK","garage"=>game.World.Changes.FamilyKeys?"F / UNLOCK GARAGE":"F / LOCKED GARAGE / FIND THE KEYS","cache"=>game.World.Changes.FamilyGarageClaimed?"GARAGE STORES / EMPTY":"F / SEARCH GARAGE STORES","basement"=>"F / DESCEND TO THE BASEMENT","photo"=>"F / EXAMINE FAMILY PHOTOGRAPH","letter"=>"F / READ KITCHEN NOTE",_=>""};
 bool FamilyInteract(){string op=FamilyOperation();if(op=="")return false;if(!CoopRequest("family",op))FamilyAction(op);return true;}
 void FamilyAction(string operation){if(CoopClient||operation!=FamilyOperation())return;var state=game.World.Changes;switch(operation){case "exit":case "basement":if(CoopHost&&coopActor>0){game.Notice="Ask the host to lead the party between upstairs and basement";return;}if(operation=="exit")ExitDungeon();else EnterDungeon(FamilyDungeon());break;
  case "shelf":game.Notice="The shelving collapsed across the door / break it with aimed axe swings or gunfire";break;
  case "door":if(state.FamilyShelfDamage<54||state.FamilyDoorOpened)return;if(game.Change(()=>state.FamilyDoorOpened=true)){SpawnFamilyFrail(true);game.Notice="Something moves in the dark";if(CoopHost&&coopActors.Count>0)Rpc(nameof(CoopFamilyScare));FamilyScare();}break;
  case "keys":if(game.Change(()=>state.FamilyKeys=true))game.Notice="Garage keys taken / the locked stores are upstairs";break;
  case "garage":if(!state.FamilyKeys){game.Notice="Locked / the spare keys were taken into the safe room";return;}game.Change(()=>state.FamilyGarageOpen=true);game.Notice="The garage lock opens";break;
  case "cache":if(!state.FamilyGarageOpen||state.FamilyGarageClaimed)return;if(game.Change(()=>{state.FamilyGarageClaimed=true;game.Craft.Materials[0]+=12;game.Craft.Materials[1]+=8;game.Craft.Materials[2]+=10;game.Craft.Materials[3]+=8;game.Craft.UnlockedTier=Math.Max(2,game.Craft.UnlockedTier);game.Craft.Reserve+=96;game.Life.Bandages+=6;game.Life.Food+=4;game.Craft.Water+=4;game.Profile.Claim(new ExpeditionRelic{Id=$"family/garage/{game.Save.Seed}",Name="Willow mechanic's reinforced gloves",Origin="Willow House garage",Slot="hands",Level=2,Armor=10,Vitality=5});}))game.Notice="Garage supplies packed / ammunition, dressings, provisions, water, materials and reinforced gloves";break;
  case "photo":ReadFamilyNote(0);break;case "letter":ReadFamilyNote(1);break;case "journal":ReadFamilyNote(2);break;
 }if(CoopHost&&coopActors.Count>0)Rpc(nameof(CoopWorldUpdate),Json.Write(WorldSnapshot()));}
 void ReadFamilyNote(int index){if(!game.Change(()=>{string id="family/note/"+index;if(!game.Profile.Journal.Seen.Contains(id))game.Profile.Journal.Seen.Add(id);game.AwardResearch("discovery/"+id,2);}))return;if(CoopHost&&coopActor>0)RpcId(coopActor,nameof(CoopFamilyNote),index);else ShowFamilyNote(index);}
 void ShowFamilyNote(int index){if(index<0||index>=FamilyTitles.Length)return;var box=Panel(FamilyTitles[index]);Text(box,FamilyNotes[index]);Button(box,"BACK",CloseMenu);}
 [Rpc(MultiplayerApi.RpcMode.Authority,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopFamilyNote(int index){if(CoopClient)ShowFamilyNote(index);}
 [Rpc(MultiplayerApi.RpcMode.Authority,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopFamilyScare(){if(CoopClient&&InFamilyRoom)FamilyScare();}
 void FamilyScare(){if(!InFamilyRoom)return;hurtShake=.12;EnemySound(new(0,0,-8),1);}
 bool IsFamilyShelf(Node collider)=>InFamilyRoom&&game.World.Changes.FamilyShelfDamage<54&&GodotObject.IsInstanceValid(familyShelf)&&collider!=null&&(collider==familyShelf||familyShelf.IsAncestorOf(collider));
 void DamageFamilyShelf(int damage){if(!InFamilyRoom||game.World.Changes.FamilyShelfDamage>=54)return;if(game.Change(()=>game.World.Changes.FamilyShelfDamage=Math.Min(54,game.World.Changes.FamilyShelfDamage+damage))){ImpactParticles(new(0,.8f,-6.5f),Wood,8,.06f);game.Notice=game.World.Changes.FamilyShelfDamage>=54?"The broken shelf falls clear of the door":"The shelf splinters";if(CoopHost&&coopActors.Count>0)Rpc(nameof(CoopWorldUpdate),Json.Write(WorldSnapshot()));}}
 bool ChopFamilyShelf(){if(!InFamilyRoom)return false;var q=PhysicsRayQueryParameters3D.Create(camera.GlobalPosition,camera.GlobalPosition-camera.GlobalBasis.Z*3.5f);q.Exclude=new(){player.GetRid()};var hit=GetWorld3D().DirectSpaceState.IntersectRay(q);if(hit.Count==0||!IsFamilyShelf(hit["collider"].AsGodotObject() as Node))return false;if(game.Clock<nextChop)return true;nextChop=game.Clock+.75;if(game.Stamina<8){game.Notice="Too exhausted to break the shelf";return true;}game.Stamina-=8;DamageFamilyShelf(18);Sound(4);return true;}
 void SpawnFamilyFrail(bool lunge){if(CoopClient||game.Skills.Defeated.Contains(FamilyInfectedId)||infected.Any(e=>e.Id==FamilyInfectedId))return;AddEnemy(FamilyInfectedId,0,-9.5,2);var e=infected.FirstOrDefault(e=>e.Id==FamilyInfectedId);if(e==null)return;e.Hp=e.MaxHp=1;e.Visual.Scale=new(.72f,.95f,.72f);e.Body.Rotation=new(0,Mathf.Pi,0);e.Memory=8;e.Target=player.Position;e.Cooldown=1.2;e.BossTime=lunge?.32:0;e.BossState=lunge?"family-lunge":"";e.BossAim=new(0,0,-5.3f);}
 bool TickFamilyLunge(Infected e,double dt){if(e.Id!=FamilyInfectedId||e.BossTime<=0)return false;e.BossTime=Math.Max(0,e.BossTime-dt);var direction=e.BossAim-e.Body.Position;direction.Y=0;e.Body.Velocity=direction.Length()>.3f?direction.Normalized()*11:Vector3.Zero;e.Body.MoveAndSlide();AnimateCharacter(e);if(e.BossTime<=0)e.BossState="";return true;}
 void DrawFamilyHouse(double dt){if(InFamilyRoom){if(game.World.Changes.FamilyShelfDamage>=54&&GodotObject.IsInstanceValid(familyShelf)){familyShelf.QueueFree();familyShelf=null;}if(GodotObject.IsInstanceValid(familySafeDoor)&&game.World.Changes.FamilyDoorOpened){SetCollisions(familySafeDoor,false);familySafeDoor.Rotation=new(0,Mathf.LerpAngle(familySafeDoor.Rotation.Y,-Mathf.Pi/2,Math.Min(1,(float)dt*5)),0);}if(GodotObject.IsInstanceValid(familyLamp))familyLamp.LightEnergy=1.1f+.12f*Mathf.Sin(Time.GetTicksMsec()/1000f*6.3f)+.06f*Mathf.Sin(Time.GetTicksMsec()/1000f*2.7f);}else if(GodotObject.IsInstanceValid(familyGarageDoor)&&game.World.Changes.FamilyGarageOpen){SetCollisions(familyGarageDoor,false);familyGarageDoor.Rotation=new(0,Mathf.LerpAngle(familyGarageDoor.Rotation.Y,-Mathf.Pi/2,Math.Min(1,(float)dt*4)),0);}}
}
